 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Uso para resolver um problemão prático da minha rotina atual (consertar algo em casa, trocar um aparelho que está travando, comprar algo realmente útil).',5,false) RETURNING id INTO alternative_id;
