 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Chegou uma caixa na sua casa com um produto que precisa ser instalado ou montado por você. Como você reage?','O eletrodoméstico ou móvel desmontado',2,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Abro a caixa e começo a mexer por intuição. Gosto de testar, encaixar e ver como funciona na prática. Só vou atrás de tutorial ou manual se sobrar peça ou travar muito.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q02','Q02:A',question_id,alternative_id,'{"P":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Antes de tocar em qualquer peça, procuro um vídeo detalhado ou leio as instruções para entender a lógica da montagem inteira. Preciso saber o passo a passo para não errar.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q02','Q02:B',question_id,alternative_id,'{"E":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Se perceber que vai tomar muito tempo ou dar muito trabalho manual, prefiro agilizar: chamo alguém que entende, divido a tarefa com alguém ou pago um profissional para resolver logo.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q02','Q02:C',question_id,alternative_id,'{"L":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Acho mais legal fazer disso um momento dinâmico. Chamo alguém para me ajudar, coloco uma música, vou conversando e transformo a montagem em uma atividade de parceria.',4,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q02','Q02:D',question_id,alternative_id,'{"C":3,"H":2}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'É sexta-feira à noite e você está pensando no seu final de semana. O que você realmente quer que aconteça nos próximos dois dias?','O final de semana ideal',3,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Quero ver gente, dar risada, sair da mesmice e ter momentos descontraídos com amigos ou família para esquecer o peso da semana.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q03','Q03:A',question_id,alternative_id,'{"C":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Quero aproveitar o tempo livre para resolver pendências pessoais, adiantar algumas metas ou planejar os passos das semanas que estão por vir.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q03','Q03:B',question_id,alternative_id,'{"L":4,"E":1}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Não quero deixar nada rigidamente planejado. Prefiro ficar livre para decidir na hora o que der vontade de fazer, sem horários ou obrigações.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q03','Q03:C',question_id,alternative_id,'{"C":3,"P":2}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Quero um tempo calmo e silencioso para mim. Ler, assistir algo que estimule minha mente, organizar meu espaço e colocar os pensamentos em ordem.',4,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q03','Q03:D',question_id,alternative_id,'{"E":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Quero focar em descansar o corpo e fazer atividades manuais ou práticas que me acalmem (cozinhar algo gostoso, cuidar das minhas coisas, organizar a casa no meu ritmo).',5,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q03','Q03:E',question_id,alternative_id,'{"P":4}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Imagine que surge uma oportunidade inesperada para você mudar radicalmente de área de atuação, de rotina ou até de cidade. Qual é a primeira coisa que passa pela sua cabeça?','A proposta de mudança radical',4,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Sinto um frio na barriga, mas me empolgo com o movimento. Penso logo no crescimento que isso pode me trazer e nas novas portas que vão se abrir para o meu futuro.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q04','Q04:A',question_id,alternative_id,'{"L":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'A primeira coisa que faço é colocar no papel: custos, estabilidade, os prós e os contras. Só consigo cogitar a mudança se o cenário me der segurança e clareza.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q04','Q04:B',question_id,alternative_id,'{"E":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Fico animada com a novidade e com a chance de conhecer pessoas e lugares novos, mas logo me pergunto se eu realmente vou me adaptar e me sentir pertencente a esse novo estilo de vida.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q04','Q04:C',question_id,alternative_id,'{"C":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Minha mente vai direto nas pessoas que dependem de mim ou que estão ao meu redor. Só consigo aceitar se eu tiver certeza de que essa mudança não vai desestruturar ou prejudicar quem eu amo.',4,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q04','Q04:D',question_id,alternative_id,'{"H":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Penso em como seria o dia a dia prático dessa nova realidade. Se a rotina de trabalho for muito engessada ou o processo lento demais, prefiro recusar e manter minha autonomia atual.',5,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q04','Q04:E',question_id,alternative_id,'{"P":4}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Sabe aquele projeto, curso, livro ou rotina que você começou com muita energia e empolgação, mas acabou deixando pelo caminho após algumas semanas? Olhando para trás, o que aconteceu de verdade?','O projeto abandonado',5,false) RETURNING id INTO question_id;
