 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Minha rotina diária engoliu meu tempo. Fiquei exausta com o trabalho, casa ou obrigações e o projeto virou um peso insuportável na minha semana.',2,false) RETURNING id INTO alternative_id;
