 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Encabeço a missão: se puder pagar alguém para resolver um desses problemas, ou pedir para alguém fazer no meu lugar enquanto eu resolvo o principal, prefiro agilizar para me livrar logo disso.',3,false) RETURNING id INTO alternative_id;
