 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Um amigo muito próximo te liga ou manda mensagem no meio da noite visivelmente mal, chorando por causa de um problema pessoal grave. Qual é a sua postura natural nessa situação?','O amigo deprimido',8,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Ouço com toda a atenção do mundo, deixo ele desabafar o tempo que precisar, acolho a dor dele e tento fazer com que ele se sinta totalmente compreendido e amado naquele momento.',1,false) RETURNING id INTO alternative_id;
