 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Me coloco à disposição de forma prática: "Estou indo aí na sua casa", "Quer que eu compre um remédio?", "Quer comer algo?". Prefiro agir fisicamente para ajudar a pessoa no que for útil.',3,false) RETURNING id INTO alternative_id;
