 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Tento usar o otimismo para mudar a energia da pessoa. Converso, conto histórias, lembro de superações passadas e tento distraí-la ou arrancar um sorriso para aliviar o clima pesado.',4,false) RETURNING id INTO alternative_id;
