 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Entro em modo obsessivo de pesquisa. Passo semanas comparando cada detalhe técnico, leio dezenas de avaliações, faço planilhas e só compro quando tenho certeza absoluta de que é a opção mais segura e inteligente.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q09','Q09:A',question_id,alternative_id,'{"E":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Se eu perceber uma oportunidade muito boa ou sentir que aquilo vai destravar a minha vida e me dar o retorno que preciso, eu fecho o negócio rápido. Não fico cozinhando a decisão por meses se o objetivo estiver claro.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q09','Q09:B',question_id,alternative_id,'{"L":3,"P":2}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Fico super empolgada no começo, pesquiso várias opções lindas e converso com todo mundo sobre isso. Em alguns momentos o processo fica cansativo e, se demorar demais, eu acabo deixando para lá ou focando em outra coisa na hora.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q09','Q09:C',question_id,alternative_id,'{"C":4}'::jsonb);
