 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Sinto uma descarga instantânea de estresse. Minha cabeça dá um nó na hora e eu demoro um tempo para conseguir respirar e reorganizar o dia depois de um susto desses.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q10','Q10:A',question_id,alternative_id,'{"H":3}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Entro no modo automático de execução. Desligo o registro, limpo o que dá, aviso sobre o atraso sem sofrimento e já começo a resolver o conserto ali mesmo. Resolvo primeiro, me estresso depois.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q10','Q10:B',question_id,alternative_id,'{"P":3,"L":2}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Minha mente já começa a calcular o custo, o tempo de reparo e quem é a melhor pessoa para resolver isso para mim. Ligo para um profissional ou para alguém que possa me ajudar na hora enquanto eu sigo meu caminho.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q10','Q10:C',question_id,alternative_id,'{"L":3,"E":2}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Minha primeira preocupação é se isso vai afetar as outras pessoas de casa ou quem está me esperando no compromisso. Tento avisar todo mundo com muito carinho para que ninguém se prejudique pelo meu imprevisto.',4,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q10','Q10:D',question_id,alternative_id,'{"H":4,"C":1}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Você se arruma, enfrenta o trânsito, chega ao local de uma consulta ou reunião importante e, ao falar com a recepção, percebe que errou feio: o compromisso era no mesmo horário, só que no dia anterior (ou na semana que vem). O que você faz?','O erro no compromisso',11,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Fico arrasada comigo mesma. Começo a me culpar mentalmente pelo erro, fico remoendo o descuido o dia todo e pensando em como eu pude ser tão desatenta. O humor cai na hora.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q11','Q11:A',question_id,alternative_id,'{"E":4}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Fico brava na hora, mas respiro fundo e mudo o chip imediatamente. Já que estou ali na rua, aproveito para resolver outra coisa, fazer um lanche ou invento um plano B para o meu tempo não ser perdido.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q11','Q11:B',question_id,alternative_id,'{"P":3,"C":1}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Tento dar um jeitinho na hora. Converso com a recepção com um sorriso no rosto, conto o meu perrengue de forma leve, tento encaixar uma vaga de última hora ou dou um jeito de ser atendida mesmo estando errada.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q11','Q11:C',question_id,alternative_id,'{"C":4}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'O grupo de WhatsApp da família, dos amigos ou de um evento começa a pegar fogo. Duas pessoas entram em uma discussão feia, trocando textões e indiretas pesadas. Qual é a sua reação real enquanto lê as mensagens?','O conflito no grupo de WhatsApp',12,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Entro em modo espectador. Acho aquela lavação de roupa suja uma perda de tempo total, muto o grupo e deixo eles se resolverem lá. Não gasto um pingo da minha energia com aquilo.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q12','Q12:A',question_id,alternative_id,'{"P":4,"E":1}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Sinto um desconforto enorme com o clima pesado. Minha vontade é intervir, mandar uma mensagem privada para tentar acalmar os ânimos ou mandar uma piada/meme no grupo para quebrar o gelo e mudar o foco.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q12','Q12:B',question_id,alternative_id,'{"C":4,"H":2}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Fico observando em silêncio e analisando quem está com a razão. Tento entender o ponto de vista de cada um e o motivo do mal-entendido, mas só falo algo se for uma opinião muito neutra e justa.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q12','Q12:C',question_id,alternative_id,'{"E":4}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Você tenta descansar e se vê com algumas horas completamente livres na sua semana. Não tem nenhuma obrigação pendente, ninguém te chamou para sair e a sua casa está organizada. O silêncio e o vazio se instalam. O que a sua mente faz?','O momento de tédio',13,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Se eu ficar muito tempo parada sem fazer nada produtivo, começo a ficar agoniada. Logo invento um projeto, vou estudar algo, arrumar um armário ou planejar a minha semana. Preciso sentir que estou me movimentando.',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q13','Q13:A',question_id,alternative_id,'{"L":4,"E":1}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Aproveito para desligar o mundo. Deito no sofá, assisto a uma série leve, navego pelas redes sociais sem rumo e deixo o tempo passar sem culpa nenhuma. Se der para dormir, melhor ainda.',2,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q13','Q13:B',question_id,alternative_id,'{"P":4,"C":1}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Minha mente começa a borbulhar de ideias ou pensamentos soltos. Sinto vontade de criar algo, ligar para alguém para conversar, buscar uma novidade na internet ou pesquisar um assunto aleatório que me deu curiosidade.',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q13','Q13:C',question_id,alternative_id,'{"C":4}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Quando as pessoas que convivem com você no dia a dia vão elogiar quem você é, qual dessas frases mais combina com o que você costuma ouvir (ou gostaria de ouvir)?','O elogio recebido (Peso Reduzido contra Viés de Autoimagem)',14,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'"Você é uma pessoa muito inteligente, focada e disciplinada. Quando você bota uma coisa na cabeça ou faz um plano, você vai lá e faz acontecer."',1,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q14','Q14:A',question_id,alternative_id,'{"L":2,"E":1}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'"Você tem uma energia incrível e uma luz que contagia o ambiente. É impossível ficar triste perto de você, você conversa com todo mundo e anima qualquer lugar."',2,false) RETURNING id INTO alternative_id;
