 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'"Você tem um coração gigante. É a pessoa mais generosa, empática e acolhedora que eu conheço. Sabe ouvir como ninguém e sempre se importa de verdade com os outros."',3,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q14','Q14:C',question_id,alternative_id,'{"H":2}'::jsonb);
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'"Você é pau pra toda obra, super prática e resolve os perrengues sem enrolação. Se eu tiver um problema real e precisar de uma solução direta, você é a primeira pessoa para quem eu ligo."',4,false) RETURNING id INTO alternative_id;
 INSERT INTO dna_private.revision_options(revision,question_key,alternative_key,question_id,alternative_id,weights) VALUES('dna-official-2026-10-26.v1','Q14','Q14:D',question_id,alternative_id,'{"P":2}'::jsonb);
 INSERT INTO public.questions(questionnaire_id,text,description,"order",active) VALUES(qid,'Um grupo de amigos decide organizar uma festa surpresa ou um churrasco de confraternização de última hora. Qual papel você assume mais naturalmente na preparação?','A organização da festa (Ajustada com Humanizado Puro)',15,false) RETURNING id INTO question_id;
 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Eu assumo o comando e coloco ordem: divido quem vai comprar o quê, defino o local, cobro o dinheiro da galera no Pix e garanto que o evento saia do papel rápido.',1,false) RETURNING id INTO alternative_id;
