 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Fico responsável pela planilha e pelas contas. Calculo a quantidade exata de comida e bebida por pessoa para não faltar e nem sobrar, pesquiso os melhores preços e organizo os horários.',2,false) RETURNING id INTO alternative_id;
