 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Meu foco é a energia do evento: cuido do grupo do WhatsApp, faço os convites, escolho a música, agito as pessoas para irem e garanto que todo mundo se divirta e se conheça na festa.',3,false) RETURNING id INTO alternative_id;
