 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Prefiro ajudar nos bastidores práticos: vou junto comprar as coisas, ajudo a carregar as caixas, arrumo o espaço, limpo ou preparo o que for preciso. Só quero ser útil para o negócio dar certo.',4,false) RETURNING id INTO alternative_id;
