 INSERT INTO public.alternatives(question_id,text,"order",active) VALUES(question_id,'Meu foco é garantir que ninguém fique de fora, que todo mundo se sinta bem acolhido e confortável no grupo. Preocupo-me em agradar o gosto de cada um e em manter o clima super gostoso e sem atritos.',5,false) RETURNING id INTO alternative_id;
